2: import { type ArrowExpression } from '@jsep-plugin/arrow';
3: import { type NewExpression } from '@jsep-plugin/new';
4: import { type TemplateElement, type TemplateLiteral } from '@jsep-plugin/template';
5: import { jsep } from './evaluator';
6: import { globalsAsync } from './globals';
7: 
8: /**
9:  * `extractVariableNames()` is a companion function for `evaluate()` and `evaluateAsync()` which extracts the
10:  * names of all unbound identifiers used in the expression. The idea is to be able to extract all of the names
11:  * of variables that will need to be supplied in order to correctly process the expression.
12:  *
13:  * @example
14:  * ```ts
15:  * // variables will be ['isEmpty', 'array']
16:  * const variables = extractVariableNames('!isEmpty(array)')
17:  * ```
18:  *
19:  * An identifier is considered "unbound" if it is not a reference to the property of an object, is not defined
20:  * as a parameter to an inline arrow function, and is not a global value. E.g.,
21:  *
22:  * @example
23:  * ```ts
24:  * // variables will be ['obj']
25:  * const variables = extractVariableNames('obj.prop()')
26:  * ```
27:  *
28:  * @example
29:  * ```ts
30:  * // variables will be ['arr', 'needle']
31:  * const variables = extractVariableNames('arr.filter(v => v === needle)')
32:  * ```
33:  *
34:  * @example
35:  * ```ts
36:  * // variables will be ['myVar']
37:  * const  variables = extractVariableNames('new String(myVar)')
38:  * ```
39:  *
40:  * Note that because this expression evaluator uses a restricted definition of "global" there are some Javascript
41:  * globals that will be reported as a unbound expression. This is expected because the evaluator will still fail
42:  * on these expressions.
43:  *
44:  * @param expression The expression to analyze, either as a string or pre-parsed expression.
45:  * @returns An array of variable names that are unbound in the expression.
46:  */
47: export function extractVariableNames(expression: string | jsep.Expression) {
48:   if (typeof expression !== 'string' && (typeof expression !== 'object' || !expression || !('type' in expression))) {
49:     throw `Unknown expression type ${expression}. Expressions must either be a string or pre-compiled string.`;
50:   }
51: 
52:   const context = createAsynchronousContext();
53:   visitExpression(typeof expression === 'string' ? jsep(expression) : expression, context);
54: 
55:   return [...context.variables];
56: }
57: 
58: function visitExpression(expression: jsep.Expression, context: EvaluationContext) {
59:   switch (expression.type) {
60:     case 'UnaryExpression':
61:       return visitUnaryExpression(expression as jsep.UnaryExpression, context);
62:     case 'BinaryExpression':
63:       return visitBinaryExpression(expression as jsep.BinaryExpression, context);
64:     case 'ConditionalExpression':
65:       return visitConditionalExpression(expression as jsep.ConditionalExpression, context);
66:     case 'CallExpression':
67:       return visitCallExpression(expression as jsep.CallExpression, context);
68:     case 'ArrowFunctionExpression':
69:       return visitArrowFunctionExpression(expression as ArrowExpression, context);
70:     case 'MemberExpression':
71:       return visitMemberExpression(expression as jsep.MemberExpression, context);
72:     case 'ArrayExpression':
73:       return visitArrayExpression(expression as jsep.ArrayExpression, context);
74:     case 'SequenceExpression':
75:       return visitSequenceExpression(expression as jsep.SequenceExpression, context);
76:     case 'NewExpression':
77:       return visitNewExpression(expression as NewExpression, context);
78:     case 'Literal':
79:       return visitLiteral(expression as jsep.Literal, context);
80:     case 'Identifier':
81:       return visitIdentifier(expression as jsep.Identifier, context);
82:     case 'TemplateLiteral':
83:       return visitTemplateLiteral(expression as TemplateLiteral, context);
84:     case 'TemplateElement':
85:       return visitTemplateElement(expression as TemplateElement, context);
86:     default:
87:       throw `Expression evaluator does not support expression of type '${expression.type}'`;
88:   }
89: }
90: 
91: function visitUnaryExpression(expression: jsep.UnaryExpression, context: EvaluationContext) {
92:   visitExpression(expression.argument, context);
93: }
94: 
95: function visitBinaryExpression(expression: jsep.BinaryExpression, context: EvaluationContext) {
96:   visitExpression(expression.left, context);
97:   visitExpression(expression.right, context);
98: }
99: 
100: function visitConditionalExpression(expression: jsep.ConditionalExpression, context: EvaluationContext) {
101:   visitExpression(expression.consequent, context);
102:   visitExpression(expression.test, context);
103:   visitExpression(expression.alternate, context);
104: }
105: 
106: function visitCallExpression(expression: jsep.CallExpression, context: EvaluationContext) {
107:   visitExpression(expression.callee, context);
108:   expression.arguments?.map(handleNullableExpression(context));
109: }
110: 
111: function visitArrowFunctionExpression(expression: ArrowExpression, context: EvaluationContext) {
112:   const boundNames = new Set(context.boundNames);
113:   for (const param of expression.params ?? []) {
114:     if (param?.type === 'Identifier') {
115:       boundNames.add((param as jsep.Identifier).name);
116:     }
117:   }
118: 
119:   visitExpression(expression.body, { ...context, boundNames });
120: }
